    /// <summary>fractions: Fraction (in Typhon.Runtime).</summary>
    internal static class fractions
    {
        public static Typhon.Runtime.Fraction Fraction(long numerator = 0, long denominator = 1) => new Typhon.Runtime.Fraction(numerator, denominator);
        public static Typhon.Runtime.Fraction Fraction(Typhon.Runtime.Fraction f) => f;
        public static Typhon.Runtime.Fraction Fraction(BigInteger numerator, BigInteger denominator) => new Typhon.Runtime.Fraction(numerator, denominator);
        public static Typhon.Runtime.Fraction Fraction(BigInteger numerator) => new Typhon.Runtime.Fraction(numerator, 1);
        public static Typhon.Runtime.Fraction Fraction(double value)
        {
            if (double.IsNaN(value) || double.IsInfinity(value)) throw new ArgumentException($"cannot convert {value} to Fraction");
            var (n, d) = Builtins.as_integer_ratio(value);
            return new Typhon.Runtime.Fraction(n, d);
        }
        public static Typhon.Runtime.Fraction Fraction(string text)
        {
            text = text.Trim();
            int slash = text.IndexOf('/');
            if (slash >= 0) return new Typhon.Runtime.Fraction(BigInteger.Parse(text.Substring(0, slash).Trim()), BigInteger.Parse(text.Substring(slash + 1).Trim()));
            int dot = text.IndexOf('.');
            if (dot < 0) return new Typhon.Runtime.Fraction(BigInteger.Parse(text), 1);
            var digits = text.Substring(dot + 1);
            return new Typhon.Runtime.Fraction(BigInteger.Parse(text.Remove(dot, 1)), BigInteger.Pow(10, digits.Length));
        }
    }

