                                          long optionflags = 0, object? extraglobs = null, bool raise_on_error = false, bool exclude_empty = false) => new TestResults(0, 0);
        public static void run_docstring_examples(object f, object globs, bool verbose = false, string name = "NoName", object? compileflags = null, long optionflags = 0) { }
        public const long ELLIPSIS = 8, NORMALIZE_WHITESPACE = 4;
    }

    /// <summary>timeit for callables (a statement given as a string would need an interpreter).</summary>
    internal static class timeit_
    {
        public static double timeit(Action stmt, object? setup = null, object? timer = null, long number = 1000000, object? globals = null)
        {
            if (setup is Action prepare) prepare();
            var sw = System.Diagnostics.Stopwatch.StartNew();
            for (long i = 0; i < number; i++) stmt();
            return sw.Elapsed.TotalSeconds;
        }
        public static double default_timer() => time_.perf_counter();
    }
